mapper.select:
SELECT DATE(bet_date) as date, COUNT(*) as betCount, SUM(bet_amount) as totalBetAmount, SUM(CASE WHEN win_amount IS NOT NULL THEN win_amount ELSE 0 END) as totalWinAmount, SUM(CASE WHEN win_amount IS NOT NULL THEN win_amount ELSE 0 END) - SUM(bet_amount) as netProfit, COUNT(CASE WHEN result = 1 THEN 1 END) as winCount, COUNT(CASE WHEN result = 2 THEN 1 END) as loseCount, 0 as drawCount FROM betting_record WHERE user_id = #{userId} AND deleted = 0
AND bet_date >= #{startDate}
AND bet_date <= #{endDate}
GROUP BY DATE(bet_date) ORDER BY DATE(bet_date) DESC

SELECT league, COUNT(*) as betCount, SUM(bet_amount) as totalBetAmount, SUM(CASE WHEN win_amount IS NOT NULL THEN win_amount ELSE 0 END) as totalWinAmount, SUM(CASE WHEN win_amount IS NOT NULL THEN win_amount ELSE 0 END) - SUM(bet_amount) as netProfit, COUNT(CASE WHEN result = 1 THEN 1 END) as winCount, COUNT(CASE WHEN result = 2 THEN 1 END) as loseCount, 0 as drawCount, ROUND(COUNT(CASE WHEN result = 1 THEN 1 END) * 100.0 / COUNT(*), 2) as winRate FROM betting_record WHERE user_id = #{userId} AND deleted = 0
AND bet_date >= #{startDate}
AND bet_date <= #{endDate}
GROUP BY league ORDER BY betCount DESC

SELECT bet_type as betType, COUNT(*) as betCount, SUM(bet_amount) as totalBetAmount, SUM(CASE WHEN win_amount IS NOT NULL THEN win_amount ELSE 0 END) as totalWinAmount, SUM(CASE WHEN win_amount IS NOT NULL THEN win_amount ELSE 0 END) - SUM(bet_amount) as netProfit, COUNT(CASE WHEN result = 1 THEN 1 END) as winCount, COUNT(CASE WHEN result = 2 THEN 1 END) as loseCount, 0 as drawCount, ROUND(COUNT(CASE WHEN result = 1 THEN 1 END) * 100.0 / COUNT(*), 2) as winRate FROM betting_record WHERE user_id = #{userId} AND deleted = 0
AND bet_date >= #{startDate}
AND bet_date <= #{endDate}
GROUP BY bet_type ORDER BY betCount DESC
